//! A bounded work queue with cancellation support.
//!
//! The queue has a fixed capacity. Producers submit work items; consumers
//! (workers) pull items and execute them. Cancellation is cooperative:
//! each unit of work receives a `CancellationToken` it can poll to decide
//! whether to abort early. Closing the queue prevents new submissions,
//! and workers drain remaining items before exiting.

use std::collections::VecDeque;
use std::fmt;
use std::sync::{Arc, Condvar, Mutex};

/// Token used to signal cooperative cancellation to running work items.
#[derive(Clone, Default)]
pub struct CancellationToken {
    inner: Arc<CancellationInner>,
}

struct CancellationInner {
    cancelled: Mutex<bool>,
    condvar: Condvar,
}

impl Default for CancellationInner {
    fn default() -> Self {
        Self {
            cancelled: Mutex::new(false),
            condvar: Condvar::new(),
        }
    }
}

impl CancellationToken {
    /// Create a new, un-cancelled token.
    pub fn new() -> Self {
        Self::default()
    }

    /// Signal cancellation. Idempotent; later calls are no-ops.
    cancel(&self) {
        let mut guard = self.inner.cancelled.lock().unwrap();
        *guard = true;
        self.inner.condvar.notify_all();
    }

    /// Whether cancellation has been signalled.
    pub fn is_cancelled(&self) -> bool {
        *self.inner.cancelled.lock().unwrap()
    }

    /// Block until cancellation is signalled.
    pub fn wait_for_cancellation(&self) {
        let mut guard = self.inner.cancelled.lock().unwrap();
        while !*guard {
            guard = self.inner.condvar.wait(guard).unwrap();
        }
    }
}

/// Errors returned by queue operations.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueueError {
    /// The queue is at capacity.
    Full,
    /// The queue has been closed; no new items are accepted.
    Closed,
}

impl fmt::Display for QueueError::Full {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            QueueError::Full => write!(f, "queue is full"),
            QueueError::Closed => write!(f, "queue is closed"),
        }
    }
}

